import re

M = re.compile(r'\s*(\d+)\)(?= |$) ?')

def unq(v):
    if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
        return v[1:-1].replace('\\"', '"').replace('\\\\', '\\')
    m = re.match(r'^\(integer\) (-?\d+)$', v)
    if m:
        return int(m.group(1))
    return v

def items(n):
    if isinstance(n, tuple):
        return []
    return [n[k] for k in sorted(n)]

def lines_of(n):
    if isinstance(n, tuple):
        return [n[1]]
    out = []
    for c in items(n):
        out.extend(lines_of(c))
    return out

def kv(n):
    it = items(n)
    out = []
    for j in range(0, len(it) - 1, 2):
        k = it[j]
        key = str(k[0]) if isinstance(k, tuple) else ''
        out.append((key, k, it[j + 1]))
    return out

def scal(n):
    if isinstance(n, tuple):
        return n[0]
    return ','.join(str(x[0]) for x in items(n) if isinstance(x, tuple))

def norm(rows):
    keys = []
    for r in rows:
        for k in r:
            if k not in keys:
                keys.append(k)
    return [dict((k, r.get(k, '')) for k in keys) for r in rows]

def parse(lines):
    root = {}
    stack = []
    skip = []
    for i, ln in enumerate(lines):
        pos = 0
        marks = []
        while True:
            m = M.match(ln, pos)
            if not m:
                break
            marks.append((m.end(1), int(m.group(1))))
            pos = m.end()
        if not marks:
            continue
        for p, idx in marks:
            while stack and stack[-1][0] >= p:
                stack.pop()
            stack.append((p, idx))
        path = [x[1] for x in stack]
        node = root
        for idx in path[:-1]:
            c = node.get(idx)
            if not isinstance(c, dict):
                c = {}
                node[idx] = c
            node = c
        node[path[-1]] = (unq(ln[pos:].strip()), i)
    cmds, cl = [], []
    hist, hl = [], []
    args, al = [], []

    def walk(cmd, n, parent):
        for a in items(n):
            d = {'command': cmd, 'parent': parent}
            args.append(d)
            al.extend(lines_of(a))
            sub = None
            for key, kn, val in kv(a):
                if key == 'arguments':
                    sub = val
                else:
                    d[key] = scal(val)
            if sub is not None:
                nm = str(d.get('name', ''))
                walk(cmd, sub, parent + '.' + nm if parent else nm)

    def pairs(n, prefix):
        top = items(n)
        for j in range(0, len(top) - 1, 2):
            t = top[j]
            if not isinstance(t, tuple):
                continue
            name = str(t[0])
            if prefix and not name.startswith(prefix):
                name = name
            row = {'command': name}
            cmds.append(row)
            cl.append(t[1])
            for key, kn, val in kv(top[j + 1]):
                if isinstance(kn, tuple):
                    cl.append(kn[1])
                if key == 'history':
                    for h in items(val):
                        it = items(h)
                        hist.append({'command': name, 'version': scal(it[0]) if it else '', 'description': scal(it[1]) if len(it) > 1 else ''})
                        hl.extend(lines_of(h))
                elif key == 'arguments':
                    walk(name, val, '')
                elif key == 'subcommands':
                    pairs(val, name)
                else:
                    row[key] = scal(val)
                    cl.extend(lines_of(val))

    pairs(root, '')
    blocks = []
    if cmds:
        blocks.append({'name': 'commands', 'kind': 'table', 'lines': sorted(set(cl)), 'records': norm(cmds)})
    if hist:
        blocks.append({'name': 'history', 'kind': 'table', 'lines': sorted(set(hl)), 'records': norm(hist)})
    if args:
        blocks.append({'name': 'arguments', 'kind': 'table', 'lines': sorted(set(al)), 'records': norm(args)})
    return {'blocks': blocks, 'skip': skip}
